--
-- Table structure for table `t_gpa_history`
--

DROP TABLE IF EXISTS `t_gpa_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_gpa_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `student_id` bigint NOT NULL COMMENT '学生档案ID',
  `term` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学期',
  `gpa` decimal(4,2) NOT NULL COMMENT '学期GPA',
  `avg_gpa` decimal(4,2) DEFAULT NULL COMMENT '专业平均GPA',
  `rank` int DEFAULT NULL COMMENT '专业排名',
  `total_students` int DEFAULT NULL COMMENT '专业总人数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gpa_history` (`student_id`,`term`),
  KEY `idx_gpa_term` (`term`)
) ENGINE=InnoDB AUTO_INCREMENT=102023 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学期GPA历史';
/*!40101 SET character_set_client = @saved_cs_client */;

