--
-- Table structure for table `t_health_report`
--

DROP TABLE IF EXISTS `t_health_report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_health_report` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `student_id` bigint NOT NULL COMMENT '学生档案ID',
  `term` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学期',
  `total_score` int DEFAULT NULL COMMENT '总分',
  `items` json DEFAULT NULL COMMENT '项目明细数组',
  `report_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报告地址',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_health_report` (`student_id`,`term`)
) ENGINE=InnoDB AUTO_INCREMENT=103960 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='体测报告';
