--
-- Table structure for table `t_intervention_record`
--

DROP TABLE IF EXISTS `t_intervention_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_intervention_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `alert_id` bigint NOT NULL COMMENT '预警ID',
  `teacher_id` bigint NOT NULL COMMENT '教师档案ID',
  `intervention_date` date DEFAULT NULL COMMENT '干预日期',
  `methods` json DEFAULT NULL COMMENT '干预方式数组',
  `content` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '干预内容',
  `student_response` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学生反馈',
  `follow_up_plan` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '后续计划',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_intervention_alert` (`alert_id`)
) ENGINE=InnoDB AUTO_INCREMENT=105138 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='教师干预回填';
/*!40101 SET character_set_client = @saved_cs_client */;

