--
-- Table structure for table `t_job_cache`
--

DROP TABLE IF EXISTS `t_job_cache`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_job_cache` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台 key: boss/51job/zhilian/liepin',
  `platform_label` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台名称',
  `company_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公司名称',
  `company_size` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司规模',
  `company_stage` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司阶段',
  `job_title` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '职位名称',
  `salary_range` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '薪资范围',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市',
  `district` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区/园区',
  `education` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历要求',
  `experience` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '经验要求',
  `tags` json DEFAULT NULL COMMENT '技能标签数组',
  `highlights` json DEFAULT NULL COMMENT '亮点数组',
  `match_score` int NOT NULL DEFAULT '0' COMMENT '画像匹配度',
  `match_reasons` json DEFAULT NULL COMMENT '匹配原因数组',
  `publish_date` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发布日期',
  `source_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始链接',
  `category` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '岗位分类: backend/ai/pm/test/data/security',
  `published_at` datetime DEFAULT NULL COMMENT '平台发布时间',
  `crawled_at` datetime DEFAULT NULL COMMENT '抓取时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_job_category` (`category`),
  KEY `idx_job_match` (`match_score`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='招聘职位缓存';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `t_job_cache`
--

