DROP TABLE IF EXISTS `t_school_cache`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_school_cache` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'grad/overseas',
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '院校英文名/中文名',
  `name_zh` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '院校中文名',
  `country` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家',
  `country_emoji` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家 emoji',
  `location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在地',
  `rank` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '排名',
  `tier` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'top/good/match',
  `programs` json DEFAULT NULL COMMENT '招生专业数组',
  `admission_gpa` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '录取 GPA 要求',
  `exam_requirements` json DEFAULT NULL COMMENT '考试科目数组（考研）',
  `language_requirement` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '语言要求（留学）',
  `highlights` json DEFAULT NULL COMMENT '亮点数组',
  `match_score` int NOT NULL DEFAULT '0' COMMENT '画像匹配度',
  `match_reasons` json DEFAULT NULL COMMENT '匹配原因数组',
  `official_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '官网地址',
  `deadline` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请截止时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_school_type_tier` (`type`,`tier`),
  KEY `idx_school_match` (`match_score`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='院校库缓存';
/*!40101 SET character_set_client = @saved_cs_client */;

