DROP TABLE IF EXISTS `t_teacher`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_teacher` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `teacher_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '教师工号',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `department_id` bigint DEFAULT NULL COMMENT '所属学院ID',
  `title` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称',
  `is_class_advisor` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否班主任',
  `class_id` bigint DEFAULT NULL COMMENT '负责班级ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_teacher_id` (`teacher_id`),
  KEY `idx_teacher_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=100409 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='教师档案';
